import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int mod = Integer.parseInt(st.nextToken());

        // Fast exponentiation
        long fast_pow(int base, int exp) {
            long res = 1;
            long b = base;
            int e = exp;
            while (e > 0) {
                if ((e & 1) == 1) res = (res * b) % mod;
                b = (b * b) % mod;
                e >>= 1;
            }
            return res;
        }

        if (n % 2 == 1) {
            System.out.println(fast_pow(k, n));
        } else {
            long[] factorial = new long[n + 1];
            long[] inv_factorial = new long[n + 1];
            factorial[0] = 1;
            for (int i = 1; i <= n; i++) {
                factorial[i] = (factorial[i - 1] * i) % mod;
            }
            inv_factorial[n] = fast_pow((int) factorial[n], mod - 2);
            for (int i = n - 1; i >= 0; i--) {
                inv_factorial[i] = (inv_factorial[i + 1] * (i + 1)) % mod;
            }

            List<Integer> bits = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if ((n & (1 << i)) != 0) {
                    bits.add(i);
                }
            }

            int[] segment_lengths = new int[n + 1];
            for (int i = 0; i <= n; i++) {
                int j = i;
                while (j != 0) {
                    segment_lengths[i]++;
                    j = (j - 1) & j;
                }
            }

            boolean[] visited = new boolean[1 << n];
            Arrays.fill(visited, false);
            for (int mask = (1 << n) - 1; mask >= 0; mask--) {
                if (mask == 0) break;
                visited[mask] = true;
            }

            long[][] dp = new long[n + 1][1 << n];
            for (long[] row : dp) Arrays.fill(row, 0);
            dp[0][0] = 1;

            for (int mask = 0; mask < (1 << n); mask++) {
                for (int s = 0; s <= n; s++) {
                    if (dp[s][mask] == 0) continue;
                    for (int sub_mask = mask; sub_mask != 0; sub_mask = (sub_mask - 1) & mask) {
                        int remaining_mask = mask ^ sub_mask;
                        int l = Math.min(k, segment_lengths[remaining_mask] + 1);
                        for (int s2 = 1; s2 <= l; s2++) {
                            if (s - 1 >= 0 && s - 1 <= n && dp[s - 1][remaining_mask] != 0) {
                                long val = dp[s - 1][remaining_mask] * inv_factorial[Integer.bitCount(sub_mask)] % mod;
                                dp[s][mask] = (dp[s][mask] + val) % mod;
                            }
                        }
                    }
                }
            }

            long total = 0;
            int full_mask = (1 << n) - 1;
            int max_i = Math.min(k, segment_lengths[n]);
            for (int i = 0; i <= max_i; i++) {
                if (dp[i][full_mask] != 0) {
                    long val = dp[i][full_mask] * factorial[k] % mod;
                    val = val * inv_factorial[k - i] % mod;
                    val = val * inv_factorial[i] % mod;
                    val = val * factorial[n] % mod;
                    total = (total + val) % mod;
                }
            }
            System.out.println((fast_pow(k, n) - total + mod) % mod);
        }
    }
}
